import Foundation
import XCTest
import KwipMLCore
@testable import KwipMLApp

/// Actual fresh CPU SGD+StepLR records from eight genuine emitted Core model factories.
final class LossRecipeCompatibilityTests:XCTestCase {
    private func fixtures()throws->[String:JSONValue] {try JSONDecoder().decode([String:JSONValue].self,from:Data(Self.records.utf8))}
    private func parts(_ raw:JSONValue)throws->(GraphDocument,[String:JSONValue],JSONValue,[[String:JSONValue]]) {
        guard case .object(let record)=raw,let graph=record["graph"],case .object(let manifest)=record["manifest"],let trace=record["trace"],case .array(let metrics)=record["metrics"] else {throw WorkflowPhaseError("Fixture missing")}
        return (try JSONDecoder().decode(GraphDocument.self,from:JSONEncoder().encode(graph)),manifest,trace,try metrics.map {guard case .object(let row)=$0 else {throw WorkflowPhaseError("Metric missing")};return row})
    }
    func testGenuineEightOptimizerOwnershipRequiresSelectedObjectiveContext()throws {
        let registry=try ComponentRegistry.builtIn(),configuration=try OptimizerConfiguration(componentID:"optimizer_sgd",values:[:])
        for (id,raw) in try fixtures() {
            let(graph,manifest,_,_)=try parts(raw)
            let width=id == "loss_ctc" ? 9:["loss_cross_entropy","loss_nll","loss_kl_div"].contains(id) ? 3:2
            let expected:[JSONValue]=[.object(["name":.string("layers.head.weight"),"shape":.array([.integer(Int64(width)),2]),"dtype":.string("float32")]),.object(["name":.string("layers.head.bias"),"shape":.array([.integer(Int64(width))]),"dtype":.string("float32")])]
            guard case .object(let provenance)=manifest["provenance"],case .object(let optimizer)=provenance["optimizer"] else {throw WorkflowPhaseError("Optimizer missing")}
            XCTAssertEqual(optimizer["parameterOwnership"],.array(expected))
            XCTAssertNoThrow(try WorkflowLifecycleVerifier.validateOptimizer(manifest,expected:nil,graph:graph,expectedConfiguration:configuration,context:.explicitObjective,capturedRegistry:registry),id)
            var missing=registry;missing.components.removeAll {$0.id == "linear"}
            XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateOptimizer(manifest,expected:nil,graph:graph,expectedConfiguration:configuration,context:.explicitObjective,capturedRegistry:missing),id)
            if width != 2 || id == "loss_triplet_margin" {XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateOptimizer(manifest,expected:nil,graph:graph,expectedConfiguration:configuration),id)}
            var bad=manifest,wrong=optimizer;wrong["parameterOwnership"] = .array(Array(expected.reversed()));var p=provenance;p["optimizer"] = .object(wrong);bad["provenance"] = .object(p)
            XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateOptimizer(bad,expected:nil,graph:graph,expectedConfiguration:configuration,context:.explicitObjective,capturedRegistry:registry),id)
        }
    }
    func testGenuineEightSchedulerUsesSameCapturedObjectiveOwnership()throws {
        let registry=try ComponentRegistry.builtIn(),optimizer=try OptimizerConfiguration(componentID:"optimizer_sgd",values:[:]),schedule=try SchedulerConfiguration(componentID:"scheduler_step_lr",values:[:])
        for (id,raw) in try fixtures() {
            let(graph,manifest,trace,metrics)=try parts(raw)
            XCTAssertNoThrow(try WorkflowLifecycleVerifier.validateScheduler(manifest,expected:nil,optimizer:nil,graph:graph,trace:trace,metrics:metrics,expectedConfiguration:schedule,optimizerConfiguration:optimizer,context:.explicitObjective,capturedRegistry:registry),id)
            var missing=registry;missing.components.removeAll {$0.id == "linear"}
            XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateScheduler(manifest,expected:nil,optimizer:nil,graph:graph,trace:trace,metrics:metrics,expectedConfiguration:schedule,optimizerConfiguration:optimizer,context:.explicitObjective,capturedRegistry:missing),id)
            if ["loss_ctc","loss_cross_entropy","loss_nll","loss_kl_div","loss_triplet_margin"].contains(id) {XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateScheduler(manifest,expected:nil,optimizer:nil,graph:graph,trace:trace,metrics:metrics,expectedConfiguration:schedule,optimizerConfiguration:optimizer),id)}
            var bad=manifest
            if case .object(var metadata)=bad["rateTrace"] {metadata["records"] = 1;bad["rateTrace"] = .object(metadata)}
            XCTAssertThrowsError(try WorkflowLifecycleVerifier.validateScheduler(bad,expected:nil,optimizer:nil,graph:graph,trace:trace,metrics:metrics,expectedConfiguration:schedule,optimizerConfiguration:optimizer,context:.explicitObjective,capturedRegistry:registry),id)
        }
    }
